section.codeblock:
// The reader selected a row in the users grid.
OpenDHelp.setActivity({ focus: 'users.row' });
// They ran a command from the command palette.
OpenDHelp.setActivity({ action: 'users.invite' });
// They switched to the Permissions pane; null clears a signal.
OpenDHelp.setActivity({ pane: 'users.permissions', focus: null });

OpenDHelp.init({ docsUrl: 'https://docs.example.com', app: 'console' });
OpenDHelp.setContext({ path: location.pathname });

async function helpForNow(token) {
  const params = new URLSearchParams({ app: 'console', ...OpenDHelp.activity() });
  const res = await fetch(`https://docs.example.com/api/v1/help/context?${params}`, {
    headers: { authorization: `Bearer ${token}` },
  });
  return res.ok ? res.json() : null;
}
